### errors.ts

```ts
export type UiaErrorCode =
  | 'ERR_INVALID_RELATION'
  | 'ERR_INVALID_CARDINALITY'
  | 'ERR_NO_TRAVERSAL_PATH'
  | 'ERR_MERGE_BRANCH_UNSATISFIED'
  | 'ERR_ASSURANCE_PREDICATE_UNSATISFIED'
  | 'ERR_AUTHORITY_BINDING_MISMATCH'
  | 'CYCLE_DETECTED'
  | 'PARENT_UNRESOLVED';

export type ImplementationErrorCode =
  | 'S_SELECTOR_INCOMPATIBLE_SCHEME'
  | 'E_APPLICABLE_ASSESSMENTS_UNBRANDED'
  | 'E_TEMPORAL_FIELD_REF_INVALID'
  | 'E_CANONICALIZATION_UNSUPPORTED'
  | 'E_OWNERSHIP_UNSUPPORTED'
  | 'E_UNKNOWN_BOUNDARY_REJECTED';

export interface SpecFailure {
  kind: 'SPEC';
  code: UiaErrorCode;
  message: string;
  details?: Record<string, JsonValue>;
}

export interface MechanismFailure {
  kind: 'MECHANISM';
  code: ImplementationErrorCode;
  message: string;
  details?: Record<string, JsonValue>;
}

export type Failure = SpecFailure | MechanismFailure;

export type Result<T> = { ok: true; value: T } | { ok: false; error: Failure };

export class CanonicalizationError extends Error {
  constructor(message: string) { super(message); this.name = 'CanonicalizationError'; }
}
```

JsonValue must be defined in primitives.ts, but errors.ts references JsonValue in details. To avoid circular import, define a local JsonValue type in errors.ts or import from primitives. Better: define JsonValue in primitives.ts and import type. But primitives may need nothing from errors. Let me put JsonValue in primitives.ts and import type in errors.ts. Since errors.ts is consumed widely, and primitives consumed widely, circular? primitives doesn't import errors. errors imports primitives (type-only). Fine. But ownership needs Result, Failure. Let me structure:

