const K: readonly number[] = [0x428a2f98, ...];

function rotr(x: number, n: number): number { return ((x >>> n) | (x << (32 - n))) >>> 0; }

function sha256Bytes(input: Uint8Array): Uint8Array {
  // padding
  const bitLen = input.length * 8;
  // message length mod 512
  const totalLen = input.length + 1 + 8; // +1 for 0x80, +8 for length
  const paddedLen = Math.ceil(totalLen / 64) * 64;
  const buf = new Uint8Array(paddedLen);
